import { useAuth } from '../../context/AuthContext';
import toast from 'react-hot-toast';

const InternalManageCars = () => {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [cars, setCars] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    const pipelineCars = JSON.parse(localStorage.getItem('storeCar_pipeline_cars')) || [];
    const publishedLegacy = JSON.parse(localStorage.getItem('storeCar_published_cars')) || [];
    const mappedLegacy = publishedLegacy.map(p => ({
      _id: p.id,
      brand: p.title?.split(' ')[0] || 'Unknown',
      model: p.title?.split(' ')[1] || 'Car',
      year: 2020,
      status: p.isInternalStatus === 'sold' ? 'sold' : 'published',
      images: [p.image],
      customerName: p.user || 'Hệ thống'
    }));

    const all = [...pipelineCars, ...mappedLegacy];
    const unique = [];
    all.forEach(c => {
       if(!unique.find(x => x._id === c._id)) unique.push(c);
    });

    // Sắp xếp mới nhất lên đầu
    unique.sort((a,b) => b._id - a._id);
    setCars(unique);
  }, []);

  const handleDelete = (id) => {
    if (window.confirm('Bạn có chắc chắn muốn xóa hồ sơ này khỏi hệ thống?')) {
      const updatedCars = cars.filter(car => car._id !== id);
      setCars(updatedCars);

      const pip = updatedCars.filter(c => ['inspected','pending_approval'].includes(c.status));
      const pub = updatedCars.filter(c => ['published','sold'].includes(c.status)).map(c => ({
        id: c._id, title: `${c.brand} ${c.model}`, image: c.images?.[0], isInternalStatus: c.status
      }));

      localStorage.setItem('storeCar_pipeline_cars', JSON.stringify(pip));
      localStorage.setItem('storeCar_published_cars', JSON.stringify(pub));
      toast.success('Đã xóa hồ sơ thành công!');
    }
  };

  const filteredCars = cars.filter(car => {
    const term = searchTerm.toLowerCase();
    const searchMatch = car.brand?.toLowerCase().includes(term) || car.model?.toLowerCase().includes(term) || car.customerName?.toLowerCase().includes(term);
    if (!searchMatch) return false;

    // Phân luồng Pipeline theo Quyền
    if (user?.role === 'purchasing_staff') {
      return car.status === 'inspected';
    }
    if (user?.role === 'manager' || user?.role === 'admin') {
      return ['pending_approval', 'published', 'sold'].includes(car.status);
    }
    return true;
  });

  const getStatusBadge = (status) => {
    switch(status) {
      case 'inspected': return <span className="bg-blue-100 text-blue-700 font-bold px-3 py-1 rounded-full text-xs flex items-center gap-1 w-max"><Zap size={14}/>Chờ Thu mua xử lý</span>;
      case 'pending_approval': return <span className="bg-yellow-100 text-yellow-700 font-bold px-3 py-1 rounded-full text-xs flex items-center gap-1 w-max"><Clock size={14}/>Chờ duyệt Đăng</span>;
      case 'published': return <span className="bg-green-100 text-green-700 font-bold px-3 py-1 rounded-full text-xs flex items-center gap-1 w-max"><CheckCircle size={14}/>Đang hiển thị Web</span>;
      case 'sold': return <span className="bg-gray-200 text-gray-600 font-bold px-3 py-1 rounded-full text-xs flex items-center gap-1 w-max"><CheckCircle size={14}/>Đã Bán</span>;
      default: return <span className="bg-gray-100 text-gray-500 font-bold px-3 py-1 rounded-full text-xs flex items-center gap-1 w-max">Unknown</span>;
    }
  };

  return (
    <div className="min-h-screen bg-[#f3f7f9] py-10 px-4 font-sans">
      <div className="max-w-7xl mx-auto">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
          <div>
            <div className="flex items-center gap-2 mb-2">
              <LayoutList size={28} className="text-[#0096ff]" />
              <h1 className="text-3xl font-black text-gray-800 tracking-tight">Trung Tâm Quản Lý</h1>
            </div>
            <p className="text-gray-500 font-medium">Bảng điều khiển luồng hồ sơ xe theo cấp độ quyền hạn (Phân hệ {user?.role === 'purchasing_staff' ? 'Thu Mua' : 'Quản Lý'}).</p>
          </div>
          {user?.role === 'purchasing_staff' && (
            <button 
              onClick={() => navigate('/internal/post-car')}
              className="bg-white text-blue-600 px-5 py-2.5 rounded-xl font-bold hover:bg-blue-50 transition shadow-sm border border-blue-200"
            >
              + Đăng Xe Khách Ký Gửi
            </button>
          )}
        </div>

        <div className="bg-white rounded-3xl shadow-[0_4px_25px_rgba(0,0,0,0.03)] border border-gray-100 overflow-hidden">
          <div className="p-5 border-b border-gray-100 flex justify-between items-center bg-gray-50/50">
            <div className="relative w-full max-w-sm">
              <Search size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
              <input 
                type="text"
                placeholder="Tìm kiếm Tên xe, Khách hàng..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-4 py-2 border border-gray-200 rounded-xl text-sm focus:outline-none focus:border-[#0096ff] transition"
              />
            </div>
            <div className="text-xs font-bold text-gray-600 bg-white px-4 py-2 rounded-lg border border-gray-200 shadow-sm">
              Nhiệm vụ khả dụng: <span className="text-[#0096ff]">{filteredCars.length}</span>
            </div>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-white text-gray-400 text-xs uppercase tracking-wider border-b border-gray-100">
                  <th className="p-5 font-bold">Hình ảnh</th>
                  <th className="p-5 font-bold">Chi tiết xe</th>
                  <th className="p-5 font-bold">Khách hàng</th>
                  <th className="p-5 font-bold">Trạng thái Pipeline</th>
                  <th className="p-5 font-bold text-right">Thao tác</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {filteredCars.length > 0 ? (
                  filteredCars.map((car) => (
                    <tr key={car._id} className="hover:bg-[#f8fbff] transition-colors group">
                      <td className="p-5">
                        <div className="w-24 h-16 rounded-lg overflow-hidden border border-gray-200 shadow-sm relative bg-gray-50">
                          {car.images?.[0] ? (
                            <img src={car.images[0]} alt={car.brand} className="w-full h-full object-cover" />
                          ) : (
                            <div className="w-full h-full flex items-center justify-center text-gray-300"><span className="text-xs font-bold">NO IMG</span></div>
                          )}
                          {car.status === 'sold' && (
                            <div className="absolute inset-0 bg-gray-900/40 flex items-center justify-center">
                              <span className="text-[10px] font-bold text-white uppercase transform -rotate-12 bg-red-500/80 px-1.5 py-0.5 rounded">SOLD</span>
                            </div>
                          )}
                        </div>
                      </td>
                      <td className="p-5">
                        <div className="font-black text-gray-800 text-[15px] mb-1">{car.brand} {car.model}</div>
                        <div className="text-xs text-gray-500 font-medium">Đời {car.year} • ODO {car.mileage?.toLocaleString() || 0} km</div>
                      </td>
                      <td className="p-5">
                        <div className="text-sm font-semibold text-gray-700">{car.customerName}</div>
                      </td>
                      <td className="p-5">
                        {getStatusBadge(car.status)}
                      </td>
                      <td className="p-5 text-right">
                        <div className="flex justify-end gap-2">
                          {(car.status === 'inspected' && user.role === 'purchasing_staff') && (
                            <button 
                              onClick={() => navigate(`/internal/post-car?pipelineId=${car._id}`)}
                              className="text-xs font-bold px-4 py-2 bg-[#0096ff] text-white rounded-lg hover:bg-blue-600 transition shadow-sm flex items-center gap-1"
                            >
                              <FileEdit size={14} /> Xử lý Bài đăng
                            </button>
                          )}

                          {(car.status === 'pending_approval' && ['manager', 'admin'].includes(user.role)) && (
                            <button 
                              onClick={() => navigate(`/internal/post-car?pipelineId=${car._id}`)}
                              className="text-xs font-bold px-4 py-2 bg-yellow-500 text-white rounded-lg hover:bg-yellow-600 transition shadow-sm flex items-center gap-1"
                            >
                              <ShieldCheck size={14} /> Duyệt Phê Chuẩn
                            </button>
                          )}

                          {car.status === 'published' && ['manager', 'admin'].includes(user.role) && (
                            <button 
                              onClick={() => {
                                const localPub = JSON.parse(localStorage.getItem('storeCar_published_cars')) || [];
                                const updated = localPub.map(p => p.id === car._id ? {...p, isInternalStatus: 'sold'} : p);
                                localStorage.setItem('storeCar_published_cars', JSON.stringify(updated));
                                window.location.reload();
                              }}
                              className="text-xs font-bold px-3 py-2 bg-red-50 text-red-600 border border-red-200 rounded-lg hover:bg-red-500 hover:text-white transition"
                            >
                              Khóa (Báo Đã Bán)
                            </button>
                          )}

                          <button 
                            onClick={() => handleDelete(car._id)}
                            className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition"
                            title="Xóa vĩnh viễn"
                          >
                            <Trash2 size={16} />
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan="5" className="p-16 text-center">
                      <div className="flex flex-col items-center justify-center text-gray-400">
                        <CheckCircle size={40} className="mb-3 text-gray-300" />
                        <span className="font-bold">Bạn đã xử lý hết công việc hiện tại.</span>
                        <span className="text-sm mt-1">Hộp thư Pipeline đang trống.</span>
                      </div>
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
};

export default InternalManageCars;
